/* Section 3: Variables and tables for analyses                                             */
/* **************************************************************************************** */

/* **************************************************************************************** */
/* Sample A */

/* Code instrument for Sample A */
-- For each observation, produce additional combinations of each "simulated state" 
SELECT 						A.FISCAL_YEAR            ,
							A.EIN                    ,
							A.ACTIVITY               ,
							A.PERIOD_END             ,
							A.REVENUE_TOTAL          ,
							A.RD_REV_LESS_GRANTS     ,
							A.RD_CONTRIB_LESS_GRANTS ,
							A.RD_AVG_REV_3YR         ,
							SIMULATED_STATE = B.STATE  
INTO						SMPL_A_INSTRUMENT1

/* Create state-FIPS crosswalk */		
SELECT DISTINCT	STATEFIPS,
				STATE
INTO			STATE_FIPS_CROSSWALK				
FROM			JMP_IRS_SOI_ITEMIZED_COUNTY.dbo.[15incyallagi]
;
